#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int main() { int n; cin >> n; vector<int> first(n), position(n + 1), frequency(n); for (int &value : first) cin >> value; for (int i = 0, value; i < n; ++i) { cin >> value; position[value] = i; } for (int i = 0; i < n; ++i) ++frequency[(position[first[i]] - i + n) % n]; int best = *max_element(frequency.begin(), frequency.end()); int shift = find(frequency.begin(), frequency.end(), best) - frequency.begin(); cout << best << ' ' << shift << '\n'; }
